    [3, 3, -7, -2, 4, 5, 9, 0, 3, 4, 0],
    [2, 2, -6, -2, 4, 5, 9, -1, 2, -32, 0],
    [1, 1, -6, -1, 3, 5, 9, -1, 3, 4, 0],
    [2, 1, -6, -1, 3, 5, 10, -2, 2, -29, 0],
    [2, 3, -5, 0, 3, 5, 9, -2, 2, -1, 0],
    [3, 3, -4, -1, 3, 5, 9, -3, 1, -25, 0],
    [2, 6, -3, 0, 2, 3, 9, -4, 2, -1, 0],
    [3, 5, -3, 0, 2, 5, 9, -3, 1, -24, 0],
